definition.raw:
\label{defi-weak-solution}{\bf (Weak sub/super/solution)}\\
Let $d$ be a measurable bounded function on $\mathbb R$, and let $g\in L^2(\mathbb R)$.
We say that $w\in H^\frac{1}{2}(\mathbb R)$ is a weak supersolution for the equation
\begin{equation}\label{weak-equation}
Lw -d(x)w=g \quad \mbox{ on }\partial\Omega
\end{equation}
if, for $u:=P*_x w$ and
$$B(u,v):=\int_{\Omega}\nabla u\cdot\nabla v+\int_{\partial\Omega} d(x)(Tu)(Tv),$$
we have that
\begin{equation}\label{weak-super-solution}B(u,v)\geq \int_{\partial\Omega} gTv\quad\mbox{for all }v\in H.\end{equation}
Respectively, $w$ is a weak subsolution if
\begin{equation}\label{weak-sub-solution} B(u,v)\leq \int_{\partial\Omega} gTv\quad\mbox{for all }v\in H.\end{equation}
Accordingly, we say that $w$ is a weak solution if it is both a weak sub and supersolution.\\

we define the bilinear functional
\begin{equation}\label{bilinear-functional}
B(u,v):=\int_\Omega \nabla u \cdot\nabla v+\int_{\partial\Omega} W''(\phi)uv,\end{equation}
whose associated quadratic form is precisely
$$Q(u)=\int_\Omega|\nabla u|^2+\int_{\partial\Omega}W''(\phi)u^2,\quad u\in H.$$
It is easy to check that $B$ is a continuous and symmetric bilinear functional in $H$.

theorem.raw:
\label{th::5}{\bf (Existence and properties of the layer solution)}\\
Under assumption Ai), there exists a unique solution $\phi$ of
(\ref{eq::0bis}).
Moreover $\phi \in C^{1,\beta}_{loc}({\mathbb R})$ for some $0<\beta <1$, and there exists a constant $C>0$ such that
\begin{equation}\label{eq::5}
0<\phi'(x)\le \frac{C}{1+x^2}  \quad \mbox{for all}\quad x\in{\mathbb R}
\end{equation}
and
\begin{equation}\label{eq::6}
\left|\phi(x)-H(x)+\frac{1}{\alpha \pi x}\right| \quad \le \quad \frac{C}{x^2}   \quad \mbox{for all}\quad |x|\ge 1
\end{equation}
where $H$ is the Heaviside function and $\alpha=W''(0)$.

{\bf (Known existence and properties of the layer solution)}\label{thm-layer-solutions}\\
Let $f$ be any $\mathcal C^{1,\beta}$ function with $0 < \beta < 1$ and such that $W'= -f$. Then there exists a layer solution $u_W\in \mathcal C^{2,\beta}_{\mbox{loc}}(\overline\Omega)$ of \eqref{Cabre-SolaMorales-layer} if and only if
$$W'(0)=W'(1)=0\quad\mbox{and}\quad W> W(0)=W(1)\quad\mbox{in } (0,1).$$
Moreover,
\begin{enumerate}
\item If $W''(0), W''(1)>0$, then a layer solution of \eqref{Cabre-SolaMorales-layer} is unique up to translations in the $x$ variable, and it satisfies
\begin{equation}\label{derivative-positive}(u_W)_x>0\quad\mbox{in }\overline{\Omega}.\end{equation}
\item We have the estimate
\begin{equation}\label{gradient-bound}\abs{\nabla u_W(x,y)}\leq \frac{C}{1+\abs{(x,y)}}, \quad \mbox{for all }x\in\mathbb R, y\geq 0.\end{equation}
\item Set $\phi(x):=u_W(x,0)$. We have the bounds
\begin{equation}
\label{growth-not-sharp}\abs{\phi(x)-H(x)}\leq \frac{C}{1+\abs{x}} \quad\mbox{for all }x\in\mathbb R,
\end{equation}
\begin{equation}\label{derivative-bound}
\frac{C_1}{1+\abs{x}^2} \leq \phi'(x)\leq \frac{C_2}{1+\abs{x}^2},\quad \mbox{for all }x\in\mathbb R,
\end{equation}
for some positive constants $C,C_1,C_2$.
\item A layer solution is always a stable solution. This means that
\begin{equation}\label{stable-solution}\int_{\Omega}\abs{\nabla v}^2+\int_{\partial\Omega}W''(\phi)v^2\geq 0\end{equation}
for every function $v\in\mathcal C^1(\overline{\Omega})$ with compact support in $\overline{\Omega}$.\\
\end{enumerate}

lemma.raw:
\label{lem::2}{\bf (Computation using the ansatz)}\\
Let
$$\displaystyle{I^\varepsilon := \varepsilon \overline{v}^\varepsilon_t
+\frac{1}{\varepsilon}\left\{W'(\overline{v}^\varepsilon) -\varepsilon
  L\overline{v}^\varepsilon -\varepsilon \sigma\right\}}.$$
Then for any $i_0\in \left\{1,...,N\right\}$, we have
\begin{equation}\label{eq::12}
I^\varepsilon = e^\varepsilon_{i_0} + (\alpha \tilde{\sigma}-\sigma) +
O(\tilde{\phi}_{i_0}) \left\{\eta \overline{c}_{i_0} +\tilde{\sigma} + \sum_{i\not= i_0}
  \frac{\tilde{\phi}_i}{\varepsilon} \right\}
\end{equation}
where $\eta$ is defined in (\ref{eq::7'}) and the error
$e^\varepsilon_{i_0}$ is given by
$$e^\varepsilon_{i_0}= O(\varepsilon) + \sum_{i\not= i_0} O(\psi_i) +
\sum_{i\not= i_0} O(\tilde{\phi}_i) + \sum_{i\not= i_0}
  O\left(\frac{(\tilde{\phi}_i)^2}{\varepsilon}\right).$$

\label{lemma-equivalence}{\bf (Equivalence of solutions)}\\
Given $w\in L^{\infty}(\mathbb R)\cap \mathcal C^{1,\beta}_{\mbox{loc}}(\mathbb R)$, the following two ways of compuing $Lw$, i.e,
\begin{enumerate}
\item as a Dirichlet to Neumann operator (see section 5.3.1., in particular \eqref{eq::4}-\eqref{eq::55});

\item using the L\'evy-Khintchine formula (see theorem \ref{th::2}),
\end{enumerate}
are equivalent.

If, in addition, $w\in H^\frac{1}{2}(\mathbb R)$, then the half-Laplacian definition in term of distributions as given in theorem \ref{th::4} is also equivalent. As a consequence, the notions of viscosity and weak solutions from Definitions \ref{defi::1} and \ref{defi-weak-solution}, respectively, coincide in the smooth case.

