proposition.raw:
\label{pro::2}{\bf (Supersolution at the initial time)}\\
Under assumption (A), there exists $\delta_0>0$ such that for all
$0<\delta\le \delta_0$, we have
\begin{equation}\label{eq::8}
\overline{v}^\varepsilon(0,x)\ge v_0^\varepsilon(x) \quad \mbox{for
  all}\quad x\in{\mathbb R}
\end{equation}
for $\varepsilon >0$ small enough.

\label{pro::3}{\bf (Supersolution for positive time)}\\
Under assumption (A), there exists $\delta_0>0$ such that for all
$0<\delta\le \delta_0$ and given $T>0$, we have
\begin{equation}\label{eq::9}
\overline{v}^\varepsilon_t \ge \frac{1}{\varepsilon}
\left(L\overline{v}^\varepsilon - \frac{1}{\varepsilon}
W'(\overline{v}^\varepsilon) +\sigma(t,x) \right)   \quad \mbox{on}\quad
(0,T)\times {\mathbb R}
\end{equation}
for $\varepsilon >0$ small enough.

corollary.raw:
\label{cor-Moser}{\bf ($L^\infty$ bound when $g$ is bounded).}
Let $w\in H^{\frac{1}{2}}(\mathbb R)$ be a weak solution of \eqref{weak-equation} with non-vanishing right hand side $g$.
If there exists $p_0>1$ such that
\begin{equation}\label{eq::904}
\norm{g}_{L^p(\mathbb R)}\leq c \quad \mbox{for all}\quad p\ge p_0
\end{equation}
(with $c$ independent on $p$), then $w$ is bounded.

\label{cor-coercivity} {\bf (Coercivity).}
There exists some $C>0$ such that for all $u\in H_0$,
$$B(u,u)\geq C\norm{u}_H^2.$$

